SELECT COUNT(*)
FROM CONTENT_ACTOR
WHERE CONTENT_NO = #{contentNo}
  AND ACTOR_NO = #{actorNo}

mapper.update:
UPDATE PRODUCT_IMAGE
SET IMAGE_PATH = #{imagePath}
WHERE PRODUCT_NO = #{productNo}
  AND IS_MAIN = 'Y'

UPDATE PRODUCT
SET STATUS = 'DELETE_REQUESTED'
WHERE PRODUCT_NO = #{productNo}
  AND BUSINESS_NO = #{businessNo}
  AND STATUS != 'DELETE_REQUESTED'
